module vault_security (input clk, input rst_n, input start, input [15:0] L, input [10:0] A, input [10:0] B, output reg [31:0] insecure_count, output reg [31:0] secure_count, output reg [31:0] super_secure_count, output reg done); parameter IDLE = 3'd0; parameter CHECK_X = 3'd1; parameter CHECK_Y = 3'd2; parameter CALCULATE = 3'd3; parameter DONE = 3'd4; reg [2:0] state_reg; reg [31:0] x_reg, y_reg; reg [31:0] insecure_count_reg, secure_count_reg, super_secure_count_reg; reg done_reg; reg [31:0] total_pairs; reg [31:0] pair_count; function [31:0] gcd; input [31:0] a, b; if (b == 0) gcd = a; else gcd = gcd(a % b, b); endfunction always @(posedge clk or negedge rst_n) begin if (!rst_n) begin state_reg <= IDLE; x_reg <= 32'd1; y_reg <= 32'd0; insecure_count_reg <= 32'd0; secure_count_reg <= 32'd0; super_secure_count_reg <= 32'd0; done_reg <= 1'b0; pair_count <= 32'd0; end else begin case (state_reg) IDLE: begin if (start) begin x_reg <= 32'd1; y_reg <= - (signed)A; state_reg <= CHECK_X; end end CHECK_X: begin state_reg <= CHECK_Y; end CHECK_Y: begin state_reg <= CALCULATE; end CALCULATE: begin localparam int g1 = gcd(x_reg, y_reg + (signed)A); localparam int g2 = gcd(x_reg, (unsigned)(B - y_reg)); integer vis = (g1 == 1) + (g2 == 1); if (vis == 0) insecure_count_reg <= insecure_count_reg + 1; else if (vis == 1) secure_count_reg <= secure_count_reg + 1; else super_secure_count_reg <= super_secure_count_reg + 1; y_reg <= y_reg + 1; if (y_reg > B) begin y_reg <= - (signed)A; x_reg <= x_reg + 1; if (x_reg > L) begin done_reg <= 1'b1; state_reg <= DONE; end else begin state_reg <= CHECK_X; end end else begin state_reg <= CALCULATE; end end DONE: begin state_reg <= DONE; end endcase end end end assign insecure_count = insecure_count_reg; assign secure_count = secure_count_reg; assign super_secure_count = super_secure_count_reg; assign done = done_reg; endmodule